  if(configured){db.auth.getSession().then(async({data})=>{if(data.session){state.user=data.session.user;const {data:p}=await db.from('profiles').select('*').eq('id',state.user.id).single();if(p){state.profile=p;try{await loadLiveData();showApp()}catch(e){showLogin();setNotice('Erreur de chargement : '+e.message)}}else showLogin()}else showLogin()});db.auth.onAuthStateChange(async(event,session)=>{if(event==='PASSWORD_RECOVERY'&&session){openModal('Choisir un nouveau mot de passe',`<p class="muted" style="margin-bottom:14px">Choisissez un mot de passe respectant les règles de sécurité.</p><form id="passwordRecoveryForm" class="stack"><label>Nouveau mot de passe<input id="recoveryPassword" type="password" required minlength="10" autocomplete="new-password"></label><label>Confirmer le mot de passe<input id="recoveryPasswordConfirm" type="password" required minlength="10" autocomplete="new-password"></label></form>`,`<button class="btn primary" data-action="update-recovered-password">Enregistrer le nouveau mot de passe</button>`)}if(!session&&!state.demo){state.user=null;state.profile=null;showLogin()}})}
